const KEY='coach360-davi-v1';
const NOTE_LIMIT=2000;
const MAX_BACKUP_BYTES=20*1024*1024;
const uid=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),x=>x.toString(16).padStart(2,'0')).join('');
const initial=()=>({version:1,profile:{name:'',age:null,height:null,weight:null,calories:null,protein:null,carbs:null,fat:null,completed:false,healthNotes:''},checks:{},foods:[],sessions:[],favorites:[],activeSession:null,assessment:null,started:today()});
function today(){return new Intl.DateTimeFormat('en-CA',{timeZone:'America/Fortaleza',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}function shift(date,n){let d=new Date(date+'T12:00:00');d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)}
let state;try{state=JSON.parse(localStorage.getItem(KEY))||initial()}catch{state=initial()}
state.favorites ||= [];
state.activeSession ||= null;
if(state.profile.completed === undefined) state.profile.completed=Boolean(state.profile.name);
let pendingResume=false;
let view='inicio',level='base',workout='A',foodDate=today(),session=null,timer=null,timerEnd=0;
const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const num=(v,f=0)=>v===''||v==null?f:Number(v);const fmt=(n,d=0)=>Number(n).toLocaleString('pt-BR',{maximumFractionDigits:d});
let toastTimeout=null;
function toast(t){if(toastTimeout)clearTimeout(toastTimeout);$('#toast').textContent=t;$('#toast').style.display='block';toastTimeout=setTimeout(()=>$('#toast').style.display='none',4000);}
function save(candidate){
 try{
  localStorage.setItem(KEY,JSON.stringify(candidate));
  state=candidate;
  for(const id of ['#storage-error','#modal-storage-error']){const alert=$(id);if(alert)alert.hidden=true;}
  return true;
 }catch{
  const message='Alteração não salva. Mantenha esta tela aberta e tente novamente. Seus registros anteriores foram preservados.';
  for(const id of ['#storage-error','#modal-storage-error']){const alert=$(id);if(alert){alert.textContent=message;alert.hidden=false;}}
  toast(message);return false;
 }
}
function commit(change){const candidate=JSON.parse(JSON.stringify(state));change(candidate);return save(candidate);}
const icons={inicio:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',treinos:'M4 7v10 M8 5v14 M16 5v14 M20 7v10 M8 12h8',nutricao:'M12 21c-9-4-10-14-4-14 2 0 3 1 4 1s2-1 4-1c6 0 5 10-4 14z M12 8c0-4 3-6 6-5',checkin:'M8 4H4v17h16V4h-4 M8 2h8v4H8z M8 13l3 3 5-6',evolucao:'M4 4v16h17 M7 16l4-5 4 2 5-7',perfil:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M4 21v-3a8 6 0 0 1 16 0v3'};const names={inicio:'Visão geral',treinos:'Treinos',nutricao:'Alimentação',checkin:'Check-in',evolucao:'Evolução',perfil:'Meu perfil'};const svg=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[k]}"/></svg>`;
function title(a,b){$('#title').textContent=a;$('#subtitle').textContent=b}function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal()}function closeModal(){if(timer)clearInterval(timer);$('#modal').close()}
function daily(date=today()){return state.foods.filter(f=>f.date===date).reduce((a,f)=>({kcal:a.kcal+f.kcal,p:a.p+f.p,c:a.c+f.c,g:a.g+f.g}),{kcal:0,p:0,c:0,g:0})}
function weekDates(){const t=today(),dow=new Date(t+'T12:00:00').getDay(),mon=shift(t,-((dow+6)%7));return Array.from({length:7},(_,i)=>shift(mon,i))}function lastDays(n){return Array.from({length:n},(_,i)=>shift(today(),i-n+1))}function avg(a){return a.length?a.reduce((x,y)=>x+y,0)/a.length:null}
function metric(label,val,unit,note,icon='◈'){return `<div class="card"><span class="metric-icon">${icon}</span><div class="metric-label">${label}</div><div class="metric-value">${val} <small>${unit}</small></div><div class="small">${note}</div></div>`}
function bar(label,value,max,unit,color){if(!(max>0))return `<div class="row small"><span>${label}</span><span>${fmt(value)} ${unit} · sem meta</span></div>`;let p=Math.min(100,Math.max(0,value/max*100));return `<div class="row small"><span>${label}</span><span><b>${fmt(value)}</b> / ${fmt(max)} ${unit}</span></div><div class="bar"><span style="width:${p}%;${color?'background:'+color:''}"></span></div>`}
function render(){view=location.hash.slice(1)||'inicio';if(!names[view])view='inicio';$('#nav').innerHTML=Object.entries(names).map(([k,v])=>`<a href="#${k}" class="${view===k?'active':''}" ${view===k?'aria-current="page"':''}>${svg(k)}${v}</a>`).join('');$('#date-label').textContent=new Intl.DateTimeFormat('pt-BR',{day:'numeric',month:'long',timeZone:'America/Fortaleza'}).format(new Date());$('#user-name').textContent=state.profile.name||'Meu perfil';$('#user-avatar').textContent=(state.profile.name||'?').slice(0,2).toUpperCase();if(!state.profile.completed){profile();return;}({inicio:home,treinos:training,nutricao:nutrition,checkin:checkin,evolucao:evolution,perfil:profile})[view]();}
function home(){title(`Um passo de cada vez, ${state.profile.name}.`,'Seu plano, seus registros e o próximo passo.');const ds=weekDates(),s=state.sessions.filter(x=>ds.includes(x.date)),d=daily(),weights=Object.values(state.checks).filter(x=>x.weight).sort((a,b)=>a.date.localeCompare(b.date)),w=weights.at(-1),check=state.checks[today()],next=state.sessions.filter(s=>s.type!=='Cardio').length%2?'B':'A';$('#app').innerHTML=`${resumeBanner()}<div class="grid cols4">${metric('Peso de referência',w?.weight||state.profile.weight?fmt(w?.weight||state.profile.weight,1):'—','kg',w?'Último registro · '+w.date.split('-').reverse().join('/'):state.profile.weight?'Inicial informado · sem tendência':'Ainda não informado')}${metric('Treinos na semana',s.length,'/ 4','Seg · Qua · Qui · Sáb','↗')}${metric('Energia registrada',fmt(d.kcal),'kcal',reference(state.profile.calories,'kcal'),'◌')}${metric('Sono de hoje',check?.sleep!=null?fmt(check.sleep,1):'—','horas',check?.sleep!=null?'Informado no check-in':'Ainda não registrado','☾')}</div><div class="grid cols2 today-layout"><section class="hero"><div><span class="pill">SEU PRÓXIMO TREINO · CALISTENIA</span><h2>Força para hoje.<br>Constância para amanhã.</h2><p>Treino ${next} · Corpo inteiro · Até 30 minutos<br>O próximo nível começa com boa técnica.</p><div class="flex"><span class="pill">SEM ACADEMIA</span><span class="pill">NO SEU RITMO</span></div></div><div class="hero-action"><button class="lime" onclick="workout='${next}';location.hash='treinos'">Ver meu treino <span>↗</span></button></div></section><section class="card"><div class="row"><h2>Seu dia em equilíbrio</h2><span class="pill light">ALIMENTAÇÃO</span></div><div class="ring" style="--p:${state.profile.calories>0?Math.min(d.kcal/state.profile.calories*100,100):0}"><div>${fmt(d.kcal)}<small>${state.profile.calories?'de '+fmt(state.profile.calories)+' kcal':'sem meta definida'}</small></div></div>${bar('Proteínas',d.p,state.profile.protein,'g')}${bar('Carboidratos',d.c,state.profile.carbs,'g','#cfbc8a')}${bar('Gorduras',d.g,state.profile.fat,'g','#b4bbc1')}<button class="link" onclick="location.hash='nutricao'">+ Registrar alimentação</button></section></div><div class="grid cols2 today-layout"><section class="card"><div class="row"><h2>Sua semana</h2><span class="small">4 sessões planejadas</span></div><div class="schedule">${ds.map((x,i)=>`<div class="day ${x===today()?'today':''} ${s.some(z=>z.date===x)?'done':''}"><small>${['SEG','TER','QUA','QUI','SEX','SÁB','DOM'][i]}</small><strong>${+x.slice(-2)}</strong><small>${i===3?'Cardio':[0,2,5].includes(i)?'Força':'Descanso'}</small><div class="dot"></div></div>`).join('')}</div><div class="notice" style="margin-bottom:0">${check?'Seu check-in de hoje está salvo. Você pode atualizá-lo quando quiser.':'Como você está hoje? Um check-in curto ajuda a entender sua recuperação.'} <button class="link" onclick="location.hash='checkin'">${check?'Revisar':'Fazer check-in'} →</button></div></section><section class="card"><h2>Foco nas pequenas escolhas</h2>${[['01','Sono com prioridade','Tente deitar 15–30 minutos mais cedo.'],['02','Técnica antes da dificuldade','A avaliação de movimentos define o próximo passo.'],['03','Uma refeição por vez','Registre as porções; estimativas não são medidas exatas.']].map(x=>`<div class="tip"><span class="tip-num">${x[0]}</span><div><b>${x[1]}</b><p class="small">${x[2]}</p></div></div>`).join('')}</section></div>`}
const ex={squat:{name:'Sentar e levantar',target:'Pernas e glúteos',reps:10,range:'8–12',how:'Cadeira firme encostada na parede. Pés apoiados, levante e sente devagar. Joelhos acompanham os pés.',error:'Não se jogue no assento.',easy:'Cadeira mais alta ou leve apoio das mãos.',hard:'Descer lentamente; depois agachamento livre.'},push:{name:'Flexão na parede',target:'Peito e tríceps',reps:10,range:'8–12',how:'Mãos na altura do peito. Mantenha o corpo alinhado, aproxime o peito da parede e empurre.',error:'Evite deixar o quadril cair ou prender a respiração.',easy:'Aproxime os pés da parede.',hard:'Afaste os pés; depois use bancada fixa.'},bridge:{name:'Ponte de glúteos',target:'Glúteos e quadril',reps:12,range:'10–15',how:'Deitado, joelhos dobrados, pés no chão. Eleve o quadril contraindo os glúteos.',error:'Não arqueie a lombar para subir mais.',easy:'Reduza a amplitude.',hard:'Pause 2 segundos no alto.'},calf:{name:'Elevação de panturrilhas',target:'Panturrilhas e tornozelos',reps:12,range:'10–15',how:'Com apoio leve na parede, suba nas pontas dos pés e desça controlando.',error:'Não quique nem perca o equilíbrio.',easy:'Menor amplitude com apoio.',hard:'Faça a descida mais lenta.'},bird:{name:'Bird-dog',target:'Estabilidade do tronco',reps:6,range:'5–8 / lado',how:'Em quatro apoios, estenda braço e perna opostos. Pause 2 segundos; alterne lados.',error:'Não gire o quadril nem afunde a lombar.',easy:'Mova só um braço ou uma perna.',hard:'Aumente a pausa mantendo controle.'},w:{name:'Elevação dos braços em W',target:'Controle das escápulas',reps:10,range:'8–12',how:'De barriga para baixo, braços em W. Eleve suavemente mãos e cotovelos, olhando para o chão.',error:'Não eleve o queixo ou arqueie a lombar. Não substitui uma remada com resistência.',easy:'Só aproxime as escápulas.',hard:'Pause 2 segundos no alto.'}};
const routines={A:['squat','push','bridge','calf'],B:['squat','push','bird','w']};
function training(){title('Movimento com propósito.','Calistenia · quatro dias por semana · até 30 minutos');$('#app').innerHTML=`${resumeBanner()}<div class="tabs">${[['base','Retorno'],['medio','Intermediário'],['avancado','Avançado']].map(([k,v])=>`<button class="${level===k?'selected':''}" onclick="level='${k}';training()">${v}${k==='base'?'':' ↗'}</button>`).join('')}</div>${level!=='base'?`<div class="card"><span class="pill amber">AVALIAÇÃO NECESSÁRIA</span><h2 style="margin-top:18px">${level==='medio'?'Construa a base para o intermediário.':'O avançado é uma progressão, não um ponto de partida.'}</h2><p class="small">Para definir a dificuldade, precisamos conhecer sua capacidade atual. Responder não libera automaticamente movimentos avançados.</p><div class="grid cols3">${(level==='medio'?['Flexão no chão','Agachamento e afundo','Estabilidade de tronco']:['Puxadas e barra fixa','Força unilateral','Controle corporal']).map(x=>`<div class="meal"><b>${x}</b><p>Progressão individual, após avaliar técnica, tolerância e recuperação.</p></div>`).join('')}</div><div class="flex" style="margin-top:20px"><button onclick="assessment()">${state.assessment?'Revisar avaliação':'Responder avaliação'}</button><button class="ghost" onclick="level='base';training()">Usar treino de retorno</button></div>${state.assessment?'<p class="small">Avaliação salva. Exporte seu resumo para discutir a progressão com seu coach.</p>':''}</div>`:`<div class="grid cols2"><section class="card"><div class="row"><h2>Seu treino de força</h2><div class="tabs" style="margin:0">${['A','B'].map(x=>`<button class="${workout===x?'selected':''}" onclick="workout='${x}';training()">Treino ${x}</button>`).join('')}</div></div><div class="tags"><span class="tag">5 min aquecimento</span><span class="tag">até 22 min força</span><span class="tag">3 min finalização</span></div>${routines[workout].map((k,i)=>{let x=ex[k];return `<div class="exercise"><div class="exercise-number">0${i+1}</div><div><strong>${x.name}</strong><div class="small">${x.target} · 2 × ${x.range} · descanso 60–90 s</div><details><summary>Como fazer e adaptar</summary><p>${x.how}</p><p><b>Evite:</b> ${x.error}</p><p><b>Mais fácil:</b> ${x.easy}<br><b>Progressão:</b> ${x.hard}</p></details></div><span class="badge">RIR 4</span></div>`}).join('')}<button style="width:100%;margin-top:20px" onclick="startScreen()">Iniciar treino ${workout} →</button></section><div class="grid"><section class="card"><span class="pill light">QUINTA-FEIRA</span><h2 style="margin-top:16px">Respire. Caminhe. Recupere.</h2><p class="small">5 min de caminhada leve + 20 min em ritmo que permita conversar + 5 min de desaceleração e mobilidade de ombros e tornozelos.</p><button class="ghost" onclick="cardio()">Registrar caminhada</button></section><section class="card"><h2>O esforço certo</h2><p class="small"><b>RIR 4:</b> termine a série sentindo que conseguiria fazer mais quatro repetições com boa técnica. Não precisa ir à falha.</p><p class="small">Dor articular ou aguda: interrompa o movimento. Dor no peito, desmaio ou falta de ar intensa: interrompa e procure atendimento.</p></section></div></div>`}<div class="section-top"><h2>Seu ciclo de 8 semanas</h2><span class="small">Progresso pela resposta do corpo</span></div><div class="grid cols4">${[['01–02','Readaptação','Duas séries, técnica controlada e quatro repetições em reserva.'],['03–04','Consistência','Aumentar repetições dentro da faixa se a recuperação permitir.'],['05–06','Progressão','Ao atingir o topo em duas sessões, revisar uma dificuldade por vez.'],['07–08','Consolidação','Manter ou progredir. Terceira série só se couber no tempo e recuperação.']].map(x=>`<div class="week-card"><span class="small">SEMANAS ${x[0]}</span><b>${x[1]}</b><p>${x[2]}</p></div>`).join('')}</div>`}
function assessment(){const a=state.assessment||{};modal(`<h2>Seu ponto de partida</h2><p class="small">Responda pelo que já sabe. Não faça testes até a falha agora. Campos vazios significam “não sei”.</p><form id="assess"><div class="formgrid">${[['push','Flexões no chão com boa técnica'],['squat','Agachamentos controlados'],['lunge','Afundos por lado'],['plank','Prancha em segundos'],['pull','Repetições na barra fixa']].map(([k,l])=>`<div class="field"><label for="a-${k}">${l}</label><input id="a-${k}" name="${k}" type="number" min="0" max="300" value="${a[k]??''}"></div>`).join('')}<div class="field"><label for="abar">Tem barra instalada com segurança?</label><select id="abar" name="bar"><option value="nao">Não</option><option value="sim" ${a.bar==='sim'?'selected':''}>Sim</option></select></div><div class="full field"><label for="alim">Desconfortos ou observações</label><textarea id="alim" name="notes" maxlength="${NOTE_LIMIT}">${esc(a.notes||'')}</textarea></div></div><div class="flex"><button>Salvar avaliação</button><button type="button" class="ghost" onclick="closeModal()">Cancelar</button></div></form>`);$('#assess').onsubmit=e=>{e.preventDefault();const a=Object.fromEntries(new FormData(e.target));a.date=today();if(!commit(d=>{d.assessment=a;}))return;closeModal();training();toast('Avaliação salva. Nível ainda sujeito à revisão.')}}
function startScreen(resuming=false){
 pendingResume=resuming;
 if(state.activeSession&&!resuming){resumeSession();return;}
 modal(`<h2>Como você está agora?</h2><p class="small">Antes de ${resuming?'retomar':'iniciar'} o treino, confirme sua condição de hoje. O tempo segue contando ao trocar de aba ou bloquear a tela. Use “Pausar e sair” para interrompê-lo.</p><label class="check"><input type="checkbox" id="symptom">Estou com dor no peito, tontura, falta de ar incomum, palpitações ou mal-estar.</label><label class="check"><input type="checkbox" id="pain">Estou com dor articular, lesão ou limitação nova.</label><label class="check"><input type="checkbox" id="ready">Estou sem esses sintomas e tenho espaço seguro, cadeira firme e superfície antiderrapante.</label><p id="pre-error" class="alert-error"></p><div class="flex"><button onclick="beginSession()">${resuming?'Retomar treino':'Continuar para aquecimento'}</button><button class="ghost" onclick="closeModal()">Agora não</button></div>`);
}
function resumeSession(){if(state.activeSession)startScreen(true);}
function persistSession(pause=false){
 if(!session)return false;
 const now=Date.now(),wasRunning=session.running!==false;
 if(wasRunning&&session.segmentStarted!=null)session.elapsedMs=(session.elapsedMs||0)+Math.max(0,now-session.segmentStarted);
 session.running=!pause;
 session.segmentStarted=pause?null:now;
 session.updatedAt=now;
 const snapshot=JSON.parse(JSON.stringify(session));
 const ok=commit(d=>{d.activeSession=snapshot;});
 if(!ok){session.running=wasRunning;session.segmentStarted=wasRunning?now:null;}
 return ok;
}
function nextPhase(index){const previous=session.index;session.index=index;if(persistSession())sessionView();else session.index=previous;}
function pauseSession(){
 if(!session){closeModal();return;}
 if(!persistSession(true))return;
 session=null;closeModal();render();toast('Treino pausado e salvo. Continue quando puder.');
}
function pauseSavedSession(){
 if(!state.activeSession)return;
 if(!session)session=JSON.parse(JSON.stringify(state.activeSession));
 pauseSession();
}
function discardDraft(){
 if(!state.activeSession)return;
 if(!confirm('Descartar somente o treino em andamento? As sessões já concluídas serão preservadas.'))return;
 if(!commit(d=>{d.activeSession=null;}))return;
 session=null;closeModal();render();toast('Rascunho do treino descartado.');
}
function beginSession(){
 if($('#symptom').checked||$('#pain').checked){$('#pre-error').textContent='Não inicie esta sessão. Reavalie o sintoma com um profissional; dor no peito, desmaio ou falta de ar intensa exigem atendimento imediato.';return;}
 if(!$('#ready').checked){$('#pre-error').textContent='Confirme as condições para continuar.';return;}
 session=pendingResume&&state.activeSession?JSON.parse(JSON.stringify(state.activeSession)):{id:uid(),date:today(),type:workout,start:Date.now(),elapsedMs:0,exercises:routines[workout].map(key=>({key,sets:[]})),index:-1};
 if(session.running!==true||session.segmentStarted==null)session.segmentStarted=Date.now();
 session.running=true;
 if(persistSession())sessionView();
}
function sessionView(){
 if(timer)clearInterval(timer);
 const i=session.index;
 const exit='<button type="button" class="ghost" onclick="pauseSession()">Pausar e sair</button>';
 if(i===-1){$('#modal-content').innerHTML=`<span class="pill light">TREINO ${session.type} · AQUECIMENTO</span><h2 style="margin-top:16px">Prepare o corpo.</h2><p class="small">2 min de marcha leve; 1 min movimentando ombros e tornozelos; 2 min ensaiando agachamento e flexão na parede.</p><div class="timer" id="timer">05:00</div><div class="flex"><button onclick="runTimer(300)">Iniciar cronômetro</button><button class="ghost" onclick="nextPhase(0)">Aquecimento concluído</button>${exit}</div>`;return;}
 if(i>=session.exercises.length){
 $('#modal-content').innerHTML=`<span class="pill light">FINALIZAÇÃO</span><h2 style="margin-top:16px">Mais uma escolha por você.</h2><p class="small">Caminhe devagar por 3 minutos e deixe a respiração voltar ao habitual.</p><div class="timer" id="timer">03:00</div><button class="ghost" onclick="runTimer(180)">Cronometrar finalização</button><form id="finish" style="margin-top:20px"><div class="field"><label for="difficulty">Esforço geral da sessão (0–10)</label><input required id="difficulty" type="number" min="0" max="10" step="1" value="${session.effort??''}"></div><div class="field"><label for="session-note">Dor, dificuldade ou observação</label><textarea id="session-note" maxlength="${NOTE_LIMIT}">${esc(session.notes||'')}</textarea></div><p class="small">Data de início: ${session.date}. O tempo registrado exclui as pausas salvas.</p><div class="flex"><button>Salvar treino concluído</button>${exit}</div></form>`;
 $('#finish').oninput=()=>{session.effort=num($('#difficulty').value,null);session.notes=$('#session-note').value;persistSession();};
 $('#finish').onsubmit=e=>{e.preventDefault();session.effort=+$('#difficulty').value;session.notes=$('#session-note').value;if(!persistSession())return;const done={...session,duration:Math.round(session.elapsedMs/60000),completedAt:new Date().toISOString()};delete done.segmentStarted;delete done.running;if(!commit(d=>{if(!d.sessions.some(s=>s.id===done.id))d.sessions.push(done);d.activeSession=null;}))return;session=null;closeModal();render();toast('Treino concluído e salvo.');};return;
 }
 const current=session.exercises[i],x=ex[current.key];
 $('#modal-content').innerHTML=`<span class="pill light">EXERCÍCIO ${i+1} DE ${session.exercises.length} · TREINO ${session.type}</span><h2 style="margin-top:15px">${x.name}</h2><p class="small">${x.how}</p><div class="session-head"><b>2 × ${x.range} · RIR 4</b><p class="small">${x.error}<br>Mais fácil: ${x.easy}</p></div><form id="set-form">${[0,1].map(n=>{const z=current.sets[n]||{};return `<div class="set-line"><b>${n+1}</b><label>Repetições realizadas<input aria-label="Repetições série ${n+1}" name="rep${n}" type="number" min="0" max="100" required value="${z.reps??''}" placeholder="${x.reps}"></label><label>Repetições em reserva<input aria-label="RIR série ${n+1}" name="rir${n}" type="number" min="0" max="20" required value="${z.rir??''}" placeholder="4"></label></div><p class="small" id="series-status-${n}">${z.reps!=null&&z.rir!=null?'Série salva.':'Preencha para salvar esta série.'}</p>`;}).join('')}<p class="small">Dados salvos conforme você preenche. Nos exercícios por lado, registre o menor número se houver diferença.</p><div class="timer" id="timer">01:15</div><div class="flex"><button type="button" class="ghost" onclick="runTimer(75)">Descansar 75 s</button><button>Próximo exercício →</button>${exit}</div></form>`;
 $('#set-form').oninput=e=>{const form=e.currentTarget;if(!e.target.checkValidity())return;const f=new FormData(form);current.sets=[0,1].map(n=>({reps:num(f.get('rep'+n),null),rir:num(f.get('rir'+n),null)}));const ok=persistSession();current.sets.forEach((z,n)=>$('#series-status-'+n).textContent=ok?(z.reps!=null&&z.rir!=null?'Série salva.':'Rascunho salvo. Complete os dois campos.'):'Falha ao salvar. Mantenha esta tela aberta e tente novamente.');};
 $('#set-form').onsubmit=e=>{e.preventDefault();nextPhase(i+1);};
}
function runTimer(s){if(timer)clearInterval(timer);timerEnd=Date.now()+s*1000;const tick=()=>{const n=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));if($('#timer'))$('#timer').textContent=String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');if(!n){clearInterval(timer);toast('Tempo concluído. Continue quando estiver pronto.');}};tick();timer=setInterval(tick,250);}
function cancelSession(){pauseSession();}
function cardio(){modal(`<h2>Registrar caminhada</h2><p class="small">Registre apenas a atividade realmente realizada.</p><form id="cardio-form"><div class="field"><label for="cd">Data</label><input id="cd" name="date" type="date" value="${today()}" max="${today()}" required></div><div class="formgrid"><div class="field"><label for="cm">Duração em minutos</label><input id="cm" name="duration" type="number" min="1" max="240" required></div><div class="field"><label for="ce">Esforço (0–10)</label><input id="ce" name="effort" type="number" min="0" max="10" required></div></div><div class="flex"><button>Salvar caminhada</button><button type="button" class="ghost" onclick="closeModal()">Cancelar</button></div></form>`);$('#cardio-form').onsubmit=e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target));const entry={...x,id:uid(),type:'Cardio',duration:+x.duration,effort:+x.effort,exercises:[]};if(!commit(d=>{d.sessions.push(entry);} ))return;closeModal();render();toast('Caminhada registrada.')}}
const foods=[['Pão francês',50,150,4,29,2],['Arroz cozido',100,128,2.5,28,0.2],['Feijão cozido',100,76,4.8,14,0.5],['Frango grelhado',100,159,32,0,2.5],['Ovo cozido',50,73,6.5,0.3,4.8],['Queijo minas frescal',30,79,5.2,1,6],['Banana',80,78,1,20,0.1],['Iogurte natural',170,105,6,8,5.5],['Azeite',10,90,0,0,10]];
function nutrition(){
 title('Alimente sua constância.','Porções caseiras, favoritos e refeições que você pode repetir.');
 const d=daily(foodDate),list=state.foods.filter(x=>x.date===foodDate);
 $('#app').innerHTML=`<div class="row" style="margin-bottom:20px"><div><label for="food-date">Dia do registro</label><input id="food-date" type="date" value="${foodDate}" max="${today()}" onchange="if(this.value){foodDate=this.value;nutrition()}"></div><div class="flex"><button onclick="foodForm()">+ Adicionar alimento</button><button class="ghost" onclick="repeatMeal()">Repetir refeição</button></div></div><div class="grid cols4">${metric('Energia',fmt(d.kcal),'kcal',reference(state.profile.calories,'kcal'))}${metric('Proteínas',fmt(d.p,1),'g',reference(state.profile.protein,'g'))}${metric('Carboidratos',fmt(d.c,1),'g',reference(state.profile.carbs,'g'))}${metric('Gorduras',fmt(d.g,1),'g',reference(state.profile.fat,'g'))}</div><div class="grid cols2 today-layout"><section class="card"><h2>Seu diário alimentar</h2>${list.length?list.map(f=>{const idx=state.foods.indexOf(f);return `<div class="food-row row"><div><strong>${esc(f.name)}</strong><div class="small">${esc(f.meal)} · ${esc(f.portion|| (f.grams?fmt(f.grams)+' g':'Porção informada'))}<br>${fmt(f.kcal)} kcal · ${fmt(f.p,1)} g proteína</div></div><div class="flex"><button class="ghost" onclick="favoriteFood(${idx})" aria-label="Favoritar ${esc(f.name)}">☆ Favoritar</button><button class="ghost" onclick="removeFoodAt(${idx})" aria-label="Excluir ${esc(f.name)}">×</button></div></div>`;}).join(''):'<div class="empty"><strong>Comece pela sua próxima refeição.</strong>Escolha o alimento e a quantidade de porções.</div>'}<p class="small">Os totais incluem apenas o que foi registrado. Um dia incompleto não representa sua ingestão total.</p></section><section class="card"><h2>Seus favoritos</h2>${state.favorites.length?state.favorites.map((f,i)=>`<div class="meal"><b>${esc(f.name)}</b><p>${esc(f.portion||'Porção personalizada')} · ${fmt(f.kcal)} kcal</p><div class="flex"><button class="ghost" onclick="favoriteForm(${i})">Usar favorito</button><button class="link" onclick="removeFavorite(${i})" aria-label="Remover favorito ${esc(f.name)}">Remover</button></div></div>`).join(''):'<p class="small">Depois de registrar um alimento, toque em “Favoritar”. Você poderá reutilizar a mesma porção em outra refeição.</p>'}<div class="notice">Uma concha ou colher varia de tamanho. As medidas caseiras são aproximações: confirme o peso sugerido, quando possível, e ajuste conforme seu utensílio e preparo.</div></section></div><div class="notice">Metas são referências individuais, não medidas exatas do gasto. Não altere calorias com base em um único dia. ${state.profile.calories?'Referência atual: '+fmt(state.profile.calories)+' kcal.':'Nenhuma meta energética definida; você pode acompanhar porções normalmente.'}</div>`;
}
const portionUnits=[
 [{name:'pão médio',grams:50}],
 [{name:'colher de sopa cheia',grams:25}],
 [{name:'concha média',grams:100}],
 [{name:'filé médio',grams:100}],
 [{name:'ovo médio',grams:50}],
 [{name:'fatia média',grams:30}],
 [{name:'banana média (sem casca)',grams:80}],
 [{name:'pote',grams:170}],
 [{name:'colher de chá',grams:5},{name:'colher de sopa',grams:10}]
];
const reference=(value,unit)=>value>0?'Referência: '+fmt(value)+' '+unit:'Sem meta definida';
function foodForm(){
 modal(`<h2>Adicionar alimento</h2><p class="small">Escolha uma medida caseira ou informe o peso. Valores aproximados; marcas, utensílios e preparo variam.</p><form id="food-form"><div class="field"><label for="food-choice">Alimento</label><select id="food-choice"><option value="custom">Personalizado / rótulo</option>${foods.map((f,i)=>`<option value="${i}">${f[0]}</option>`).join('')}</select></div><div class="formgrid"><div class="field full"><label for="fn">Nome</label><input id="fn" name="name" required maxlength="100"></div><div class="field"><label for="meal">Refeição</label><select id="meal" name="meal"><option>Café da manhã</option><option>Almoço</option><option>Lanche</option><option>Jantar</option><option>Outra</option></select></div><div class="field"><label for="food-unit">Medida</label><select id="food-unit"><option value="custom">Porção personalizada</option></select></div><div class="field" id="quantity-field" hidden><label for="food-quantity">Quantidade de porções</label><input id="food-quantity" type="number" min="0.1" max="100" step="0.1" value="1"></div><div class="field"><label for="grams">Peso total (g), se conhecido</label><input id="grams" name="grams" type="number" min="0.1" max="5000" step="0.1"></div><div class="full small" id="portion-help" style="margin-bottom:15px"></div>${[['kcal','Calorias (kcal)'],['p','Proteínas (g)'],['c','Carboidratos (g)'],['g','Gorduras (g)']].map(([k,l])=>`<div class="field"><label for="f-${k}">${l} — total consumido</label><input id="f-${k}" name="${k}" required type="number" min="0" max="10000" step="0.1"></div>`).join('')}</div><div class="flex"><button>Salvar alimento</button><button type="button" class="ghost" onclick="closeModal()">Cancelar</button></div></form>`);
 const choice=$('#food-choice'),unit=$('#food-unit'),quantity=$('#food-quantity'),grams=$('#grams');
 const calc=()=>{if(choice.value==='custom')return;const i=+choice.value,f=foods[i];if(unit.value!=='grams')grams.value=(portionUnits[i][+unit.value].grams*Number(quantity.value)).toFixed(1);const ratio=Number(grams.value)/f[1];for(const [j,k] of ['kcal','p','c','g'].entries())$('#f-'+k).value=(f[j+2]*ratio).toFixed(1);$('#portion-help').textContent=unit.value==='grams'?'Valores estimados para o peso informado.':'Equivalência aproximada: '+grams.value+' g no total.';};
 choice.onchange=()=>{const custom=choice.value==='custom';unit.innerHTML=custom?'<option value="custom">Porção personalizada</option>':portionUnits[+choice.value].map((u,i)=>`<option value="${i}">${u.name} (~${u.grams} g)</option>`).join('')+'<option value="grams">Gramas</option>';$('#quantity-field').hidden=custom;quantity.required=!custom;grams.readOnly=!custom;grams.required=!custom;quantity.value=1;$('#portion-help').textContent='';if(custom){$('#fn').value='';grams.value='';for(const k of ['kcal','p','c','g'])$('#f-'+k).value='';}else{$('#fn').value=foods[+choice.value][0];calc();}};
 unit.onchange=()=>{const byGram=unit.value==='grams';$('#quantity-field').hidden=byGram;quantity.required=!byGram;grams.readOnly=!byGram;calc();};
 quantity.oninput=calc;grams.oninput=calc;
 $('#food-form').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));const unitText=choice.value!=='custom'&&unit.value!=='grams'?fmt(+quantity.value,1)+' × '+portionUnits[+choice.value][+unit.value].name:(f.grams?fmt(+f.grams,1)+' g':'Porção personalizada');const entry={...f,id:uid(),date:foodDate,portion:unitText,grams:num(f.grams,null),kcal:+f.kcal,p:+f.p,c:+f.c,g:+f.g};if(!commit(d=>{d.foods.push(entry);} ))return;closeModal();nutrition();toast('Alimento salvo.');};
}
function removeFoodAt(i){if(commit(d=>{d.foods.splice(i,1);} ))nutrition();}
function favoriteFood(i){const f=state.foods[i];if(state.favorites.some(x=>x.name===f.name&&x.grams===f.grams&&x.kcal===f.kcal)){toast('Esta porção já está nos favoritos.');return;}const {id,date,...template}=f;if(commit(d=>{d.favorites.push({...template,id:uid()});})){nutrition();toast('Porção adicionada aos favoritos.');}}
function removeFavorite(i){if(commit(d=>{d.favorites.splice(i,1);} ))nutrition();}
function favoriteForm(i){
 const f=state.favorites[i];
 modal(`<h2>Usar favorito</h2><p>${esc(f.name)} · ${esc(f.portion||'Porção personalizada')}</p><form id="fav-form"><div class="field"><label for="fav-times">Quantas vezes essa porção?</label><input id="fav-times" type="number" min="0.1" max="100" step="0.1" value="1" required></div><div class="field"><label for="fav-meal">Refeição</label><select id="fav-meal">${['Café da manhã','Almoço','Lanche','Jantar','Outra'].map(m=>`<option ${m===f.meal?'selected':''}>${m}</option>`).join('')}</select></div><div class="flex"><button>Adicionar ao dia ${foodDate.split('-').reverse().join('/')}</button><button type="button" class="ghost" onclick="closeModal()">Cancelar</button></div></form>`);
 $('#fav-form').onsubmit=e=>{e.preventDefault();const n=+$('#fav-times').value,copy={...f,id:uid(),date:foodDate,meal:$('#fav-meal').value,portion:n===1?f.portion:fmt(n,1)+' × ('+(f.portion||'porção favorita')+')',grams:f.grams?f.grams*n:null};for(const k of ['kcal','p','c','g'])copy[k]=+(f[k]*n).toFixed(1);if(commit(d=>{d.foods.push(copy);} )){closeModal();nutrition();toast('Favorito registrado.');}};
}
function repeatMeal(){
 const groups=[];
 for(const f of [...state.foods].sort((a,b)=>b.date.localeCompare(a.date))){let group=groups.find(g=>g.date===f.date&&g.meal===f.meal);if(!group){group={date:f.date,meal:f.meal,foods:[]};groups.push(group);}group.foods.push(f);}
 if(!groups.length){modal('<h2>Repetir refeição</h2><p>Registre uma refeição primeiro. Depois você poderá reutilizar seus alimentos e porções.</p><button onclick="closeModal()">Fechar</button>');return;}
 modal(`<h2>Repetir refeição</h2><p class="small">Copiar para ${foodDate.split('-').reverse().join('/')}. Confirme se consumiu as mesmas porções.</p><form id="repeat-form"><div class="field"><label for="repeat-choice">Refeição de origem</label><select id="repeat-choice">${groups.map((g,i)=>`<option value="${i}">${g.date.split('-').reverse().join('/')} · ${esc(g.meal)} · ${g.foods.length} alimentos</option>`).join('')}</select></div><div id="repeat-preview" class="meal"></div><div class="field" style="margin-top:15px"><label for="repeat-target">Registrar como</label><select id="repeat-target">${['Café da manhã','Almoço','Lanche','Jantar','Outra'].map(m=>`<option>${m}</option>`).join('')}</select></div><div class="flex"><button>Confirmar e adicionar alimentos</button><button type="button" class="ghost" onclick="closeModal()">Cancelar</button></div></form>`);
 const update=()=>{const g=groups[+$('#repeat-choice').value];$('#repeat-target').value=g.meal;$('#repeat-preview').innerHTML=g.foods.map(f=>`<p>${esc(f.name)} · ${esc(f.portion||(f.grams?fmt(f.grams)+' g':'porção informada'))}</p>`).join('');};$('#repeat-choice').onchange=update;update();
 $('#repeat-form').onsubmit=e=>{e.preventDefault();const g=groups[+$('#repeat-choice').value];const entries=g.foods.map(f=>({...f,id:uid(),date:foodDate,meal:$('#repeat-target').value}));if(commit(d=>{d.foods.push(...entries);} )){closeModal();nutrition();toast('Refeição copiada. Ajuste porções se necessário.');}};
}
function checkin(date=today()){title('Como você está hoje?','Um registro honesto vale mais do que um dia perfeito.');const c=state.checks[date]||{};$('#app').innerHTML=`<div class="grid cols2"><section class="card"><h2>Seu check-in diário</h2><form id="check-form"><div class="field"><label for="check-date">Data</label><input id="check-date" name="date" type="date" max="${today()}" value="${date}" required onchange="checkin(this.value)"></div><div class="formgrid">${[['weight','Peso (kg) · opcional',30,300,.1],['waist','Cintura (cm) · opcional',40,200,.1],['sleep','Horas de sono',0,24,.5],['energy','Energia (0–10)',0,10,1],['hunger','Fome (0–10)',0,10,1]].map(([k,l,min,max,step])=>`<div class="field"><label for="ck-${k}">${l}</label><input id="ck-${k}" name="${k}" type="number" min="${min}" max="${max}" step="${step}" value="${c[k]??''}"></div>`).join('')}<div class="field"><label for="ck-pain">Dor ou sintomas?</label><select id="ck-pain" name="pain"><option value="nao">Não</option><option value="sim" ${c.pain==='sim'?'selected':''}>Sim — descrever abaixo</option></select></div><div class="field full"><label for="ck-notes">Como foram alimentação, disposição e dificuldades?</label><textarea id="ck-notes" name="notes" rows="4" maxlength="${NOTE_LIMIT}" placeholder="O que funcionou? O que atrapalhou?">${esc(c.notes||'')}</textarea></div></div><label class="check"><input type="checkbox" name="foodComplete" ${c.foodComplete?'checked':''}>Registrei toda a alimentação deste dia.</label><p class="small">Os treinos são registrados na aba Treinos. Campos vazios permanecem desconhecidos.</p><button>Salvar check-in</button></form></section><section class="card"><h2>Uma ação para o próximo dia</h2><div id="feedback">${advice(c)}</div><div class="meal"><b>Sem compensações punitivas</b><p>Perdeu um treino ou comeu além do planejado? Retome a próxima ação possível. Não dobre a sessão nem pule refeições para compensar.</p></div><div class="meal"><b>Dados comparáveis</b><p>Peso pela manhã, após ir ao banheiro, antes de comer. Cintura no mesmo ponto, sem apertar a fita e após expirar normalmente.</p></div><p class="small">Orientações automáticas por regras simples. Este aplicativo não realiza consulta médica ou conversa com IA.</p></section></div>`;$('#check-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));['weight','waist','sleep','energy','hunger'].forEach(k=>d[k]=num(d[k],null));d.foodComplete=!!d.foodComplete;if(!commit(next=>{next.checks[d.date]=d;}))return;checkin(d.date);toast('Check-in salvo.')}}
function advice(c){let message=!c.date?'Seu primeiro check-in vai ajudar a escolher uma prioridade.':c.pain==='sim'?'Você relatou dor ou sintomas. Reavalie antes de treinar; procure atendimento se houver dor no peito, desmaio ou falta de ar intensa.':c.sleep!==null&&c.sleep<7?'Prioridade: reserve 15–30 minutos a mais para dormir. Evite sacrificar sono para encaixar o treino.':c.hunger>=8?'A fome está alta. Revise porções, regularidade das refeições e saciedade antes de pensar em reduzir calorias.':c.energy!==null&&c.energy<=3?'Disposição baixa: priorize recuperação e uma sessão mais leve, se estiver sem sintomas.':'Continue com o próximo treino planejado e registre uma refeição com suas porções.';return `<div class="notice">${message}</div>`}
function report(){const dates=lastDays(7),checks=dates.map(d=>state.checks[d]).filter(Boolean),ss=state.sessions.filter(s=>dates.includes(s.date)),weights=checks.filter(c=>c.weight).map(c=>c.weight),sleep=checks.filter(c=>c.sleep!=null).map(c=>c.sleep),complete=checks.filter(c=>c.foodComplete),previous=lastDays(14).slice(0,7).map(d=>state.checks[d]?.weight).filter(Boolean),wa=avg(weights),pw=avg(previous);return {dates,checks,ss,weights,sleep,complete,wa,pw,trend:weights.length>=3&&previous.length>=3?wa-pw:null}}
function evolution(){title('Evolução além da balança.','Tendências reais, com espaço para o que ainda não sabemos.');const r=report(),measure=Object.values(state.checks).filter(c=>c.weight).sort((a,b)=>a.date.localeCompare(b.date)),kcal=avg(r.complete.map(c=>daily(c.date).kcal));$('#app').innerHTML=`<div class="grid cols4">${metric('Treinos · últimos 7 dias',r.ss.length,'/ 4','Objetivo semanal')}${metric('Check-ins',r.checks.length,'/ 7','Dias com registro')}${metric('Sono médio',r.sleep.length?fmt(avg(r.sleep),1):'—','h',r.sleep.length+' dias informados')}${metric('Média de peso',r.wa?fmt(r.wa,1):'—','kg',r.trend===null?'Ainda sem comparação suficiente':(r.trend>0?'+':'')+fmt(r.trend,1)+' kg vs. 7 dias anteriores')}</div><div class="grid cols2 today-layout"><section class="card"><h2>Peso ao longo do tempo</h2><div class="chart-key"><span><i></i>Pesagens informadas</span></div>${chart(measure)}<p class="small">Compare médias. Uma pesagem isolada não determina perda de gordura.</p></section><section class="card"><h2>Leitura da semana</h2><div class="tip"><div><b>Adesão ao treino</b><p class="small">${r.ss.length} sessões registradas. O planejamento prevê 4; registros ausentes não comprovam falta.</p></div></div><div class="tip"><div><b>Alimentação</b><p class="small">${r.complete.length} dias marcados completos.${kcal!==null?' Média desses dias: '+fmt(kcal)+' kcal.':' Ainda não há base para avaliar a ingestão.'}</p></div></div><div class="tip"><div><b>Próximo ajuste</b><p class="small">${r.checks.length<7?'Complete sete dias de registros para uma revisão mais consistente.':r.checks.some(c=>c.pain==='sim')?'Reavalie os sintomas relatados antes de progredir.':avg(r.sleep)<7&&r.sleep.length?'Priorize aumentar o tempo de sono.':'Mantenha o plano e confira técnica e recuperação antes de avançar.'} Não há alteração automática de calorias ou dificuldade.</p></div></div><button class="ghost" style="margin-top:15px" onclick="exportSummary()">Exportar resumo para meu coach</button></section></div><div class="section-top"><h2>Histórico de sessões</h2></div><section class="card">${state.sessions.length?`<div class="table-wrap"><table><thead><tr><th>Data</th><th>Sessão</th><th>Tempo registrado</th><th>Esforço</th><th></th></tr></thead><tbody>${state.sessions.slice().reverse().map(s=>`<tr><td>${s.date.split('-').reverse().join('/')}</td><td>${s.type==='Cardio'?'Caminhada':'Calistenia '+esc(s.type)}</td><td>${s.duration} min</td><td>${s.effort}/10</td><td><button class="ghost" onclick="sessionDetail('${s.id}')">Detalhes</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><strong>Sua história começa no primeiro treino.</strong>As sessões concluídas aparecerão aqui.</div>'}</section>`}
function chart(data){if(data.length<2)return '<div class="empty"><strong>Aguardando duas pesagens.</strong>Sem dados fictícios: o gráfico cresce com você.</div>';let vals=data.map(x=>x.weight),min=Math.min(...vals)-1,max=Math.max(...vals)+1;let pts=data.map((x,i)=>[35+i*(430/(data.length-1)),145-(x.weight-min)/(max-min)*110]);return `<svg class="progress-chart" viewBox="0 0 500 180" role="img" aria-label="Gráfico de ${data.length} pesagens"><line x1="35" y1="145" x2="465" y2="145" stroke="#e6ebdf"/><polyline points="${pts.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#668b54" stroke-width="2.5"/>${pts.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="#668b54"><title>${data[i].date}: ${data[i].weight} kg</title></circle>`).join('')}<text class="chart-label" x="35" y="172">${data[0].date.split('-').reverse().slice(0,2).join('/')}</text><text class="chart-label" x="465" y="172" text-anchor="end">${data.at(-1).date.split('-').reverse().slice(0,2).join('/')}</text><text class="chart-label" x="35" y="20">${fmt(max-1,1)} kg · máximo observado</text></svg>`}
function sessionDetail(id){const s=state.sessions.find(x=>x.id===id);modal(`<h2>${s.type==='Cardio'?'Caminhada':'Treino '+esc(s.type)}</h2><p class="small">${s.date} · ${s.duration} minutos · esforço ${s.effort}/10</p>${s.exercises.map(x=>`<div class="meal"><b>${ex[x.key]?.name||esc(x.key)}</b><p>${x.sets.map((z,i)=>`Série ${i+1}: ${z.reps} repetições · RIR ${z.rir}`).join('<br>')}</p></div>`).join('')}<p class="small">${esc(s.notes||'Sem observações adicionais.')}</p><button onclick="closeModal()">Fechar</button>`)}
function profile(){
 const p=state.profile,first=!p.completed;
 title(first?'Seu espaço começa aqui.':'Um plano que acompanha você.',first?'Preencha apenas o que deseja guardar neste navegador.':'Seu perfil e suas referências, sob seu controle.');
 $('#app').innerHTML=`<div class="grid cols2"><section class="card"><h2>${first?'Configurar meu perfil':'Perfil e referências'}</h2><div class="notice">Suas respostas ficam neste navegador. Não são publicadas no GitHub nem enviadas ao ChatGPT. Em um dispositivo compartilhado, outras pessoas com acesso a este navegador podem vê-las.</div><form id="profile-form"><div class="field"><label for="pn">Nome ou apelido</label><input id="pn" name="name" value="${esc(p.name)}" required maxlength="40" autocomplete="given-name"></div><div class="formgrid">${[['age','Idade · opcional',18,100],['height','Altura (cm) · opcional',100,230],['weight','Peso inicial (kg) · opcional',30,300],['calories','Referência energética (kcal) · opcional',100,10000],['protein','Proteínas (g) · opcional',1,500],['carbs','Carboidratos (g) · opcional',1,1000],['fat','Gorduras (g) · opcional',1,500]].map(([k,l,min,max])=>`<div class="field"><label for="p-${k}">${l}</label><input id="p-${k}" name="${k}" value="${p[k]??''}" type="number" min="${min}" max="${max}" step="${k==='weight'?.1:1}"></div>`).join('')}</div><p class="small">Preencha metas alimentares apenas se já tiver referências individualizadas. Campos vazios permanecem sem meta; estes limites de preenchimento não são recomendações nutricionais.</p><div class="field"><label for="health-notes">Saúde, medicamentos ou limitações que deseja lembrar · opcional</label><textarea id="health-notes" name="healthNotes" maxlength="${NOTE_LIMIT}">${esc(p.healthNotes||'')}</textarea></div><p class="small">Não informar uma condição não equivale a confirmar boa saúde. Este registro não substitui uma avaliação profissional.</p><button>${first?'Começar':'Salvar perfil'}</button></form></section><div class="grid"><section class="card"><h2>Suas referências</h2><p class="small">Você pode registrar alimentação sem definir calorias ou macros. As metas existentes são referências informadas ou preservadas da versão anterior; não são uma medição do gasto energético.</p><button class="ghost" onclick="assessment()">Avaliação de calistenia</button></section><section class="card"><h2>Seus dados, com você</h2><p class="small">Não há sincronização entre dispositivos. Exporte um backup antes de trocar de navegador ou limpar seus dados. O backup inclui perfil, registros, favoritos e treino em andamento.</p><div class="flex"><button class="ghost" onclick="backup()">Exportar backup</button><button class="ghost" onclick="document.getElementById('import-file').click()">Importar backup</button><button class="ghost" onclick="exportSummary()">Resumo para o coach</button></div><input id="import-file" type="file" accept="application/json,.json" hidden onchange="restore(this.files[0])"></section></div></div>`;
 $('#profile-form').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));for(const k of ['age','height','weight','calories','protein','carbs','fat'])f[k]=num(f[k],null);if(!commit(d=>{d.profile={...f,completed:true};}))return;location.hash='inicio';render();toast('Perfil salvo neste navegador.');};
}
function download(name,text,type){const b=new Blob([text],{type}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}function backup(){download('coach360-backup-'+today()+'.json',JSON.stringify(state,null,2),'application/json');toast('Backup exportado.')}
function restore(file){
 if(!file)return;
 if(file.size>MAX_BACKUP_BYTES){toast('Backup muito grande. Limite: 20 MB.');return;}
 const rd=new FileReader();
 rd.onload=()=>{try{
 const d=validateBackup(JSON.parse(rd.result));
 if(!confirm('Substituir os registros deste navegador pelo backup? Exporte o atual primeiro se quiser preservá-lo.'))return;
 if(!save(d))return;
 session=null;closeModal();render();toast('Backup importado.');
 }catch{toast('Arquivo inválido. Use um backup exportado pelo Coach 360°.');}};
 rd.onerror=()=>toast('Não foi possível ler o arquivo.');
 rd.readAsText(file);
}
function validateBackup(d){
 const fail=()=>{throw Error('Backup inválido');};
 const object=v=>v!==null&&typeof v==='object'&&!Array.isArray(v);
 const text=(v,max=MAX_BACKUP_BYTES)=>{if(typeof v!=='string'||v.length>max)fail();return v;};
 const number=(v,min,max,optional=false)=>{if(optional&&(v===null||v===undefined))return null;if(!Number.isFinite(v)||v<min||v>max)fail();return v;};
 const date=v=>{if(typeof v!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(v)||!Number.isFinite(Date.parse(v+'T12:00:00Z'))||new Date(v+'T12:00:00Z').toISOString().slice(0,10)!==v)fail();return v;};
 const id=v=>{if(typeof v!=='string'||!/^[a-zA-Z0-9-]{8,80}$/.test(v))fail();return v;};
 if(!object(d)||d.version!==1||!object(d.profile)||!object(d.checks)||!Array.isArray(d.foods)||!Array.isArray(d.sessions))fail();
 const p=d.profile,profile={name:text(p.name,40),completed:p.completed??Boolean(p.name),healthNotes:text(p.healthNotes||'')};
 if(typeof profile.completed!=='boolean')fail();
 for(const k of ['age','height','weight','calories','protein','carbs','fat'])profile[k]=number(p[k],0,10000,true);
 const food=(f,withDate=true)=>{if(!object(f))fail();const out={id:id(f.id),name:text(f.name,100),meal:text(f.meal,50),grams:number(f.grams,0,500000,true),portion:text(f.portion||'')};
 if(withDate)out.date=date(f.date);for(const k of ['kcal','p','c','g'])out[k]=number(f[k],0,1000000);return out;};
 const workout=(s,active=false)=>{
 if(!object(s)||!['A','B','Cardio'].includes(s.type)||!Array.isArray(s.exercises))fail();
 const out={id:id(s.id),type:s.type,date:date(s.date),notes:text(s.notes||''),effort:number(s.effort,0,10,true),exercises:[]};
 if(active&&s.type==='Cardio')fail();
 if(s.type==='Cardio'){if(s.exercises.length)fail();}
 else{
 if(s.exercises.length!==4)fail();
 out.exercises=s.exercises.map((x,i)=>{
 if(!object(x)||x.key!==routines[s.type][i]||!Array.isArray(x.sets)||x.sets.length>2)fail();
 return {key:x.key,sets:x.sets.map(z=>{if(!object(z))fail();return {reps:number(z.reps,0,100,active),rir:number(z.rir,0,20,active)};})};
 });
 }
 if(active){out.index=number(s.index,-1,4);if(!Number.isInteger(out.index))fail();out.elapsedMs=number(s.elapsedMs,0,1e10,true)||0;out.start=number(s.start,0,1e15);out.updatedAt=number(s.updatedAt,0,1e15,true);out.segmentStarted=null;out.running=false;}
 else{out.duration=number(s.duration,0,100000);if(s.completedAt)out.completedAt=text(s.completedAt,40);}
 return out;
 };
 const checks={};
 for(const [key,c] of Object.entries(d.checks)){if(!object(c)||date(key)!==date(c.date)||!['sim','nao'].includes(c.pain))fail();const out={date:c.date,pain:c.pain,notes:text(c.notes||''),foodComplete:!!c.foodComplete};for(const k of ['weight','waist','sleep','energy','hunger'])out[k]=number(c[k],0,k==='sleep'?24:['energy','hunger'].includes(k)?10:500,true);checks[key]=out;}
 let assessment=null;
 if(d.assessment){if(!object(d.assessment))fail();assessment={};for(const k of ['push','squat','lunge','plank','pull']){const v=d.assessment[k];assessment[k]=v===''||v==null?'':String(number(Number(v),0,300));}assessment.bar=d.assessment.bar==='sim'?'sim':'nao';assessment.notes=text(d.assessment.notes||'');if(d.assessment.date)assessment.date=date(d.assessment.date);}
 if(d.favorites&&!Array.isArray(d.favorites))fail();
 return {version:1,profile,checks,foods:d.foods.map(f=>food(f)),sessions:d.sessions.map(s=>workout(s)),favorites:(d.favorites||[]).map(f=>food(f,false)),assessment,activeSession:d.activeSession?workout(d.activeSession,true):null,started:d.started?date(d.started):today()};
}
function exportSummary(){const r=report();let text=`COACH 360° — RESUMO PARA ACOMPANHAMENTO\nExportado: ${today()}\n\nPERFIL\n${JSON.stringify(state.profile,null,2)}\n\nPLANO\nCalistenia de retorno, 3 sessões de força alternando A/B e 1 caminhada. Até 30 min. Intermediário/avançado dependem de avaliação. Referências alimentares estimadas, não medidas.\n\nAVALIAÇÃO DE MOVIMENTOS\n${JSON.stringify(state.assessment,null,2)}\n\nÚLTIMOS 7 DIAS\nTreinos: ${r.ss.length}/4. Check-ins: ${r.checks.length}/7.\nPeso médio informado: ${r.wa??'sem registro'}. Sono médio: ${avg(r.sleep)??'sem registro'}.\n\nREGISTROS (não confundir ausência com zero)\n${JSON.stringify({checks:state.checks,sessions:state.sessions,foods:state.foods},null,2)}\n\nSolicitação ao coach: revisar adesão, sintomas, recuperação e tendência; sugerir uma prioridade. Não ajustar calorias ou dificuldade com base em um único dia.`;download('coach360-resumo-'+today()+'.txt',text,'text/plain');toast('Resumo exportado para compartilhar na conversa.')}
function resumeBanner(){return state.activeSession?`<div class="notice"><b>Você tem um treino em andamento.</b><p>Treino ${state.activeSession.type} · iniciado em ${state.activeSession.date.split('-').reverse().join('/')} · séries preservadas neste navegador.</p>${state.activeSession.running?'<p>O tempo está contando. Pause se interromper o treino.</p>':''}<div class="flex"><button onclick="resumeSession()">Continuar treino</button>${state.activeSession.running?'<button class="ghost" onclick="pauseSavedSession()">Pausar contagem</button>':''}<button class="ghost" onclick="discardDraft()">Descartar rascunho</button></div></div>`:'';}
document.addEventListener('visibilitychange',()=>{if(session)persistSession();});
window.addEventListener('pagehide',()=>{if(session)persistSession();});
window.addEventListener('hashchange',render);$('#modal').addEventListener('cancel',e=>{if(session){e.preventDefault();cancelSession()}else if(timer)clearInterval(timer)});render();

